// 1. Capturamos los datos de la API de N2YO
const data = $input.first().json.positions[0];
const satelite = $input.first().json.info.satname;
const azimuth = data.azimuth;
const elevation = data.elevation;
const eclipsed = data.eclipsed;

// 2. Función para convertir grados de Azimut en dirección humana
function obtenerDireccion(grados) {
    const sectores = [
        { nombre: "Norte (N)", min: 337.5, max: 360 },
        { nombre: "Norte (N)", min: 0, max: 22.5 },
        { nombre: "Noreste (NE)", min: 22.5, max: 67.5 },
        { nombre: "Este (E)", min: 67.5, max: 112.5 },
        { nombre: "Sureste (SE)", min: 112.5, max: 157.5 },
        { nombre: "Sur (S)", min: 157.5, max: 202.5 },
        { nombre: "Suroeste (SO)", min: 202.5, max: 247.5 },
        { nombre: "Oeste (O)", min: 247.5, max: 292.5 },
        { nombre: "Noroeste (NO)", min: 292.5, max: 337.5 }
    ];

    const encontrado = sectores.find(s => grados >= s.min && grados < s.max);
    return encontrado ? encontrado.nombre : "Desconocido";
}

const direccion = obtenerDireccion(azimuth);

// 3. Construcción del mensaje profesional
let mensaje = `🛰️ *REPORTE DE MISIÓN: ${satelite}*\n\n`;

// Sección: Ventana de Comunicación (Dinámica Orbital) [cite: 76, 118]
if (elevation >= 0) {
    mensaje += `🟢 *ESTADO:* Ventana de comunicación ABIERTA.\n`;
    mensaje += `📡 *APUNTAMIENTO:* Elevación de ${elevation.toFixed(2)}° hacia el *${direccion}* (Azimut: ${azimuth.toFixed(2)}°).\n\n`;
} else {
    mensaje += `🔴 *ESTADO:* Satélite bajo el horizonte (Elevación: ${elevation.toFixed(2)}°).\n`;
    mensaje += `⏳ *POSICIÓN:* Actualmente se encuentra hacia el ${direccion}.\n\n`;
}

// Sección: Energía (EPS) [cite: 23, 30]
if (eclipsed) {
    mensaje += `🌑 *ENERGÍA:* Satélite en ECLIPSE. Los paneles solares no cargan. Dependencia 100% de baterías.\n`;
} else {
    mensaje += `☀️ *ENERGÍA:* Recibiendo luz solar. Subsistema EPS operando con paneles solares.\n`;
}

// 4. Devolvemos el objeto para el siguiente nodo (Telegram)
return {
    mensaje: mensaje,
    lat: data.satlatitude,
    lng: data.satlongitude
};
